using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using OAS.Domain.Accounting.Entities;
using OAS.Domain.Entities.Inventory;
using OAS.Domain.Purchasing.Entities;
using OAS.Domain.Sales.Entities;

namespace OAS.Infrastructure.Purchasing.Persistence.Configurations;

public sealed class PurchaseInvoiceConfiguration : IEntityTypeConfiguration<PurchaseInvoice>
{
    public void Configure(EntityTypeBuilder<PurchaseInvoice> builder)
    {
        builder.ToTable("tbl_PurchaseInvoices", "dbo", t => { t.HasCheckConstraint("CK_PurchaseInvoices_ExchangeRate_Positive", "[ExchangeRate] > 0"); t.HasCheckConstraint("CK_PurchaseInvoices_Totals_NonNegative", "[Subtotal] >= 0 AND [DiscountAmount] >= 0 AND [TaxAmount] >= 0 AND [TotalAmount] >= 0 AND [BaseSubtotal] >= 0 AND [BaseTaxAmount] >= 0 AND [BaseTotalAmount] >= 0"); }); builder.HasKey(x => x.Id); builder.ConfigurePurchasingAudit(); builder.Property(x => x.Id).ValueGeneratedNever(); builder.Property(x => x.PurchaseInvoiceCode).IsRequired().HasMaxLength(40); builder.Property(x => x.SupplierInvoiceCode).HasMaxLength(100); builder.Property(x => x.SupplierId).IsRequired(); builder.Property(x => x.InvoiceDate).HasColumnType("date").IsRequired(); builder.Property(x => x.PostingDate).HasColumnType("date").IsRequired(); builder.Property(x => x.CurrencyId).IsRequired(); builder.Property(x => x.ExchangeRate).HasPrecision(19,8).IsRequired(); builder.Property(x => x.ExchangeRateDate).HasColumnType("date").IsRequired(); builder.Property(x => x.TaxCalculationMode).HasConversion<byte>().IsRequired(); builder.Property(x => x.Status).HasConversion<byte>().IsRequired(); builder.Property(x => x.Subtotal).HasPrecision(19,4).IsRequired(); builder.Property(x => x.DiscountAmount).HasPrecision(19,4).IsRequired(); builder.Property(x => x.TaxAmount).HasPrecision(19,4).IsRequired(); builder.Property(x => x.TotalAmount).HasPrecision(19,4).IsRequired(); builder.Property(x => x.BaseSubtotal).HasPrecision(19,4).IsRequired(); builder.Property(x => x.BaseTaxAmount).HasPrecision(19,4).IsRequired(); builder.Property(x => x.BaseTotalAmount).HasPrecision(19,4).IsRequired(); builder.Property(x => x.JournalEntryId); builder.Property(x => x.Notes).HasMaxLength(1000); builder.Property(x => x.ConfirmedBy).HasMaxLength(64); builder.Property(x => x.ConfirmedAt).HasColumnType("datetimeoffset"); builder.Property(x => x.PostedBy).HasMaxLength(64); builder.Property(x => x.PostedAt).HasColumnType("datetimeoffset"); builder.Property(x => x.CancelledBy).HasMaxLength(64); builder.Property(x => x.CancelledAt).HasColumnType("datetimeoffset"); builder.Property(x => x.CancellationReason).HasMaxLength(500); builder.Property(x => x.RowVersion).IsRowVersion().IsConcurrencyToken(); builder.HasIndex(x => x.PurchaseInvoiceCode).IsUnique().HasDatabaseName("UX_PurchaseInvoices_PurchaseInvoiceCode"); builder.HasIndex(x => new { x.SupplierId, x.SupplierInvoiceCode }).IsUnique().HasFilter("[SupplierInvoiceCode] IS NOT NULL").HasDatabaseName("UX_PurchaseInvoices_Supplier_SupplierInvoiceCode"); builder.HasIndex(x => x.SupplierId).HasDatabaseName("IX_PurchaseInvoices_SupplierId"); builder.HasIndex(x => x.InvoiceDate).HasDatabaseName("IX_PurchaseInvoices_InvoiceDate"); builder.HasIndex(x => x.PostingDate).HasDatabaseName("IX_PurchaseInvoices_PostingDate"); builder.HasIndex(x => x.Status).HasDatabaseName("IX_PurchaseInvoices_Status"); builder.HasOne<Supplier>().WithMany().HasForeignKey(x => x.SupplierId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PurchaseInvoices_Suppliers_SupplierId"); builder.HasOne<Currency>().WithMany().HasForeignKey(x => x.CurrencyId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PurchaseInvoices_Currencies_CurrencyId"); builder.HasOne<JournalEntry>().WithMany().HasForeignKey(x => x.JournalEntryId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PurchaseInvoices_JournalEntries_JournalEntryId"); builder.HasMany(x => x.Lines).WithOne().HasForeignKey(x => x.PurchaseInvoiceId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("FK_PurchaseInvoiceLines_Invoices_PurchaseInvoiceId"); builder.Navigation(x => x.Lines).UsePropertyAccessMode(PropertyAccessMode.Field);
    }
}
